import 'dart:async'; import 'package:flutter/material.dart'; import '../_game_utils.dart';
class EndlessRunnerGame extends StatefulWidget{const EndlessRunnerGame({super.key});@override State<EndlessRunnerGame> createState()=>_S();}
class _S extends State<EndlessRunnerGame>{double y=0;int score=0;late Timer t;@override void initState(){super.initState();t=Timer.periodic(const Duration(milliseconds:250),(_){if(mounted)setState(()=>score++);});}@override void dispose(){t.cancel();super.dispose();}void jump(){setState(()=>y=-.4);Future.delayed(const Duration(milliseconds:450),(){if(mounted)setState(()=>y=0);});if(score>50)finishGame(context,score,true);}@override Widget build(c)=>GameShell(title:'Endless Runner',onRestart:()=>setState(()=>score=0),child:GestureDetector(onTap:jump,child:CustomPaint(painter:_P(y),size:const Size(double.infinity,double.infinity))));}
class _P extends CustomPainter{final double y;_P(this.y);@override void paint(Canvas c,Size s){final p=Paint();c.drawRect(Rect.fromLTWH(30,s.height-70+y*s.height,45,45),p);c.drawRect(Rect.fromLTWH(s.width-100,s.height-90,40,65),p);}@override bool shouldRepaint(c)=>true;}
